import type { Collectible, CollectionCategory, CollectionMetric, Destination, Rarity } from './registry';

/**
 * THE BIG EXPANSION: 166 more collectibles across all six rarities (Common to Mythic). Written as compact
 * rows (`rarity|name|emoji|fun fact`) per category, then expanded into full `Collectible`s here, so the
 * unlock rules are generated by ONE formula instead of 166 hand-typed numbers:
 *
 *  - Common..Legendary: a VERIFIED metric (sounds, words, Play & Learn plays, lessons, tracing pages, voice
 *    practice, My Day steps, stars, streak, Talk taps, Daily Missions, speech practice) at a threshold that
 *    rises with the rarity. The metric rotates item by item, so no single activity unlocks everything.
 *  - Mythic: the rarest tier is earned by FINDING MANY OTHER collectibles (100, 120 ... 200), so it can only
 *    come from sustained, real practice.
 *
 * Art is the emoji (offline-safe, like the learning content) on a rarity-coloured plate: `emoji:<char>`.
 */
const R: Record<string, Rarity> = { c: 'common', u: 'uncommon', r: 'rare', e: 'epic', l: 'legendary', m: 'mythic' };
const TIER: Record<Rarity, number> = { common: 0, uncommon: 1, rare: 2, epic: 3, legendary: 4, mythic: 5 };

/** Thresholds per metric, by rarity (common .. legendary). */
