/**
 * The unlock rule for the n-th (0-based) collectible of a rarity: a verified metric whose threshold rises with the
 * rarity and, slowly, with n (capped at 4x), so a thousand items are a long road and never an impossible one.
 * Mythic is "find N others"; the registry spaces those thresholds evenly once it knows the total.
 */
export function ruleFor(rarity: Rarity, n: number): Pick<Collectible, 'condition' | 'hint' | 'destination'> {
  if (rarity === 'mythic') return { condition: { kind: 'collected', at: 100 }, hint: 'Find 100 collectibles.', destination: 'progress' };
  const s = SCALE[n % SCALE.length];
  const at = Math.round(s.at[TIER[rarity]] * Math.min(4, 1 + 0.05 * Math.floor(n / SCALE.length)));
  return { condition: { kind: 'metric', metric: s.metric, at }, hint: s.hint(at), destination: s.to };
}

/** Running count per rarity, shared with the generated expansion so thresholds keep climbing across both. */
export const RARITY_COUNTS: Record<Rarity, number> = { common: 0, uncommon: 0, rare: 0, epic: 0, legendary: 0, mythic: 0 };

function expand(): Collectible[] {
  const out: Collectible[] = [];
  for (const category of Object.keys(ROWS) as CollectionCategory[]) {
    for (const row of ROWS[category]) {
      const [r, name, emoji, fact] = row.split('|');
      const rarity = R[r];
      const n = RARITY_COUNTS[rarity]++;
      const id = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
      out.push({ id, name, category, rarity, art: `emoji:${emoji}`, fact, ...ruleFor(rarity, n) });
    }
  }
  return out;
}

export const EXTRA_COLLECTION: Collectible[] = expand();
